<?php
session_start();
$DB_HOST='localhost';$DB_NAME='sembako_pos';$DB_USER='root';$DB_PASS='';
try{$pdo=new PDO("mysql:host=$DB_HOST;dbname=$DB_NAME;charset=utf8mb4",$DB_USER,$DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}catch(Throwable $e){die('<meta name="viewport" content="width=device-width,initial-scale=1"><div style="font:16px system-ui;max-width:700px;margin:10vh auto;padding:24px"><h2>Database belum siap</h2><p>Pastikan MySQL aktif, lalu buka <a href="setup.php">setup.php</a>.</p></div>');}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function rupiah($n){return 'Rp '.number_format((float)$n,0,',','.');}function go($p='dashboard'){header('Location: index.php?page='.$p);exit;}
if(isset($_GET['logout'])){session_destroy();header('Location: index.php');exit;}
$loginError='';if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['login'])){$s=$pdo->prepare('SELECT * FROM users WHERE username=?');$s->execute([trim($_POST['username']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['username']=$u['username'];header('Location: index.php');exit;}else $loginError='Username atau password salah.';}
if(!isset($_SESSION['uid'])){?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Masuk • Sembako POS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#eff5f2;font-family:system-ui}.login{max-width:420px;margin:8vh auto;background:white;padding:32px;border-radius:22px;box-shadow:0 18px 55px #1232}.brand{color:#087f63}</style></head><body><main class="login"><div class="brand fw-bold fs-4 mb-2">▦ SEMBAKO POS</div><p class="text-secondary">Masuk ke sistem toko Anda</p><?php if($loginError)echo '<div class="alert alert-danger">'.h($loginError).'</div>';?><form method="post"><label class="form-label">Username</label><input class="form-control form-control-lg mb-3" name="username" required autocomplete="username"><label class="form-label">Password</label><input class="form-control form-control-lg mb-4" type="password" name="password" required autocomplete="current-password"><button class="btn btn-success btn-lg w-100" name="login" value="1">Masuk</button></form><small class="text-secondary d-block mt-4">Akun awal setelah setup: pemilik / GantiSaya123!</small></main></body></html><?php exit;}
$page=$_GET['page']??'dashboard';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['save_product'])){try{$id=(int)($_POST['id']??0);$d=[trim($_POST['sku']),trim($_POST['name']),trim($_POST['category']),trim($_POST['unit']),max(0,(float)$_POST['cost_price']),max(0,(float)$_POST['sell_price']),max(0,(float)$_POST['stock']),max(0,(float)$_POST['min_stock'])];if($id){$q=$pdo->prepare('UPDATE products SET sku=?,name=?,category=?,unit=?,cost_price=?,sell_price=?,stock=?,min_stock=? WHERE id=?');$q->execute([...$d,$id]);}else{$q=$pdo->prepare('INSERT INTO products(sku,name,category,unit,cost_price,sell_price,stock,min_stock) VALUES(?,?,?,?,?,?,?,?)');$q->execute($d);}$_SESSION['flash']='Barang berhasil disimpan.';go('barang');}catch(Throwable $e){$msg='Gagal menyimpan barang. Pastikan SKU tidak duplikat.';}}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['delete_product'])){$q=$pdo->prepare('DELETE FROM products WHERE id=? AND id NOT IN (SELECT product_id FROM sale_items)');try{$q->execute([(int)$_POST['id']]);$_SESSION['flash']=$q->rowCount()?'Barang dihapus.':'Barang pernah terjual dan tidak dapat dihapus.';}catch(Throwable $e){$_SESSION['flash']='Barang tidak dapat dihapus karena sudah memiliki transaksi.';}go('barang');}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['checkout'])){try{$cart=json_decode($_POST['cart_json']??'[]',true);if(!is_array($cart)||!count($cart))throw new Exception('Keranjang kosong.');$method=$_POST['payment_method']??'Tunai';if(!in_array($method,['Tunai','QRIS','Transfer'],true))throw new Exception('Metode pembayaran tidak valid.');$pdo->beginTransaction();$lines=[];$subtotal=0;foreach($cart as $item){$pid=(int)($item['id']??0);$qty=(float)($item['qty']??0);if($qty<=0)throw new Exception('Jumlah barang tidak valid.');$q=$pdo->prepare('SELECT * FROM products WHERE id=? FOR UPDATE');$q->execute([$pid]);$p=$q->fetch();if(!$p||$p['stock']<$qty)throw new Exception('Stok tidak cukup untuk '.($p['name']??'barang'));$line=$qty*(float)$p['sell_price'];$subtotal+=$line;$lines[]=[$p,$qty,$line];}$paid=max(0,(float)($_POST['paid']??0));if($method==='Tunai'&&$paid<$subtotal)throw new Exception('Uang yang diterima kurang.');if($method!=='Tunai')$paid=$subtotal;$invoice='INV'.date('ymdHis').random_int(10,99);$q=$pdo->prepare('INSERT INTO sales(invoice,subtotal,total,paid,change_amount,payment_method,status) VALUES(?,?,?,?,?,?,?)');$q->execute([$invoice,$subtotal,$subtotal,$paid,max(0,$paid-$subtotal),$method,'Lunas']);$sid=(int)$pdo->lastInsertId();foreach($lines as [$p,$qty,$line]){$q=$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,product_name,qty,unit,price,cost_price,line_total) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$sid,$p['id'],$p['name'],$qty,$p['unit'],$p['sell_price'],$p['cost_price'],$line]);$q=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');$q->execute([$qty,$p['id']]);}$pdo->commit();$_SESSION['flash']='Transaksi '.$invoice.' berhasil dicatat.';go('transaksi');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$msg=$e->getMessage();}}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['save_expense'])){$q=$pdo->prepare('INSERT INTO expenses(title,amount,expense_date) VALUES(?,?,?)');$q->execute([trim($_POST['title']),max(0,(float)$_POST['amount']),$_POST['expense_date']]);$_SESSION['flash']='Pengeluaran dicatat.';go('laporan');}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['change_password'])){if(!password_verify($_POST['current_password']??'', $pdo->query('SELECT password FROM users WHERE id='.(int)$_SESSION['uid'])->fetchColumn()))$msg='Password saat ini salah.';elseif(strlen($_POST['new_password']??'')<10)$msg='Password baru minimal 10 karakter.';elseif(($_POST['new_password']??'')!==($_POST['confirm_password']??''))$msg='Konfirmasi password tidak cocok.';else{$q=$pdo->prepare('UPDATE users SET password=? WHERE id=?');$q->execute([password_hash($_POST['new_password'],PASSWORD_DEFAULT),$_SESSION['uid']]);$msg='Password berhasil diubah.';}}
if(isset($_SESSION['flash'])){$msg=$_SESSION['flash'];unset($_SESSION['flash']);}
$today=date('Y-m-d');$todaySales=(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM sales WHERE DATE(created_at)='$today'")->fetchColumn();$todayCount=(int)$pdo->query("SELECT COUNT(*) FROM sales WHERE DATE(created_at)='$today'")->fetchColumn();$lowStock=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE stock<=min_stock')->fetchColumn();$productCount=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();$gross=(float)$pdo->query("SELECT COALESCE(SUM(si.line_total-si.qty*si.cost_price),0) FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE DATE(s.created_at)='$today'")->fetchColumn();$products=$pdo->query('SELECT * FROM products ORDER BY name')->fetchAll();$categories=$pdo->query('SELECT DISTINCT category FROM products ORDER BY category')->fetchAll(PDO::FETCH_COLUMN);$sales=$pdo->query('SELECT * FROM sales ORDER BY id DESC LIMIT 100')->fetchAll();$edit=null;if($page==='barang'&&isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM products WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
