;display:flex;flex-direction:column}.cart-lines{overflow:auto;flex:1}.cart-line{padding:12px 0;border-bottom:1px solid #edf1ef}.form-control,.form-select{border-radius:10px;padding:10px 12px}.btn{border-radius:10px}.badge-soft{background:#e8f6f0;color:var(--green)}.mobile-nav{display:none}@media(max-width:1050px){.sidebar{width:205px}.main{margin-left:205px;padding:20px}.pos-layout{grid-template-columns:minmax(0,1fr) 310px}}@media(max-width:780px){.sidebar{display:none}.main{margin:0;padding:16px 13px 84px}.topbar{align-items:flex-start}.topbar h1{font-size:24px}.mobile-nav{display:flex;position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:1px solid #e5ece8;z-index:20;justify-content:space-around;padding:8px 2px calc(8px + env(safe-area-inset-bottom));gap:2px}.mobile-nav a{font-size:11px;text-decoration:none;color:#61736c;text-align:center;flex:1}.mobile-nav a span{display:block;font-size:20px}.metric{padding:15px}.pos-layout{display:flex;flex-direction:column}.cart-panel{position:static;height:auto;min-height:0}.cart-lines{max-height:280px}.product-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important}.wide-only{display:none}.table-wrap{overflow-x:auto}.topbar .user-label{display:none}}@media(max-width:390px){.product-grid{gap:8px!important}.product-card{padding:10px;min-height:135px}.main{padding-left:10px;padding-right:10px}.metric strong{font-size:19px}}@media print{.sidebar,.mobile-nav,.topbar,.no-print{display:none!important}.main{margin:0;padding:0}.card{box-shadow:none}}</style></head><body>
<aside class="sidebar"><div class="brand">▦ SEMBAKO POS</div><div class="text-uppercase text-secondary small px-3 mb-2">Menu utama</div><?php $menus=['dashboard'=>['⌂','Dashboard'],'kasir'=>['▣','Kasir / POS'],'barang'=>['▦','Data Barang'],'transaksi'=>['▤','Riwayat Transaksi'],'laporan'=>['▥','Laporan & Keuangan'],'pengaturan'=>['⚙','Pengaturan']];foreach($menus as $k=>$v)echo '<a class="nav-link '.($page===$k?'active':'').' d-flex gap-3" href="?page='.$k.'"><span>'.$v[0].'</span>'.$v[1].'</a>';?><div class="mt-5 px-3 small text-secondary">Login sebagai<br><b class="text-dark"><?=h($_SESSION['username'])?></b><br><a href="?logout=1" class="text-danger text-decoration-none d-inline-block mt-3">Keluar ↗</a></div></aside>
