<?php if($page==='dashboard'):?><div class="row g-3 mb-4"><div class="col-6 col-xl-3"><div class="card metric"><small>Penjualan hari ini</small><strong><?=rupiah($todaySales)?></strong><span class="muted mt-2">Total omzet</span></div></div><div class="col-6 col-xl-3"><div class="card metric"><small>Transaksi hari ini</small><strong><?=$todayCount?></strong><span class="muted mt-2">Transaksi tercatat</span></div></div><div class="col-6 col-xl-3"><div class="card metric"><small>Estimasi laba kotor</small><strong><?=rupiah($gross)?></strong><span class="muted mt-2">Sebelum biaya operasional</span></div></div><div class="col-6 col-xl-3"><div class="card metric"><small>Stok perlu dicek</small><strong><?=$lowStock?></strong><span class="muted mt-2">Produk di bawah batas minimum</span></div></div></div><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 fw-bold">Aksi cepat</h2></div><div class="row g-3 mb-4"><div class="col-6 col-lg-3"><a class="card p-3 text-decoration-none text-dark h-100" href="?page=kasir"><div class="product-icon">＋</div><b class="mt-3">Transaksi baru</b><span class="muted">Mulai penjualan</span></a></div><div class="col-6 col-lg-3"><a class="card p-3 text-decoration-none text-dark h-100" href="?page=barang"><div class="product-icon">▦</div><b class="mt-3">Kelola barang</b><span class="muted">Harga dan stok</span></a></div><div class="col-6 col-lg-3"><a class="card p-3 text-decoration-none text-dark h-100" href="?page=transaksi"><div class="product-icon">▤</div><b class="mt-3">Riwayat transaksi</b><span class="muted">Lihat penjualan</span></a></div><div class="col-6 col-lg-3"><a class="card p-3 text-decoration-none text-dark h-100" href="?page=laporan"><div class="product-icon">▥</div><b class="mt-3">Laporan</b><span class="muted">Penjualan dan biaya</span></a></div></div><div class="card p-3 p-lg-4"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 fw-bold mb-0">Stok perlu diperhatikan</h2><a href="?page=barang" class="small text-success">Lihat semua</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Barang</th><th>Stok</th><th>Minimum</th><th>Status</th></tr></thead><tbody><?php $low=$pdo->query('SELECT * FROM products WHERE stock<=min_stock ORDER BY stock ASC LIMIT 8')->fetchAll();if(!$low)echo '<tr><td colspan="4" class="text-center text-secondary">Semua stok di atas batas minimum.</td></tr>';foreach($low as $p)echo '<tr><td>'.h($p['name']).'</td><td>'.h($p['stock']).' '.h($p['unit']).'</td><td>'.h($p['min_stock']).'</td><td><span class="badge text-bg-warning">Perlu restock</span></td></tr>';?></tbody></table></div></div>
<?php elseif($page==='kasir'):?><div class="pos-layout"><section><div class="d-flex gap-2 mb-3"><input id="searchProduct" class="form-control" placeholder="Cari nama barang atau SKU..." autofocus><select id="categoryFilter" class="form-select" style="max-width:170px"><option value="">Semua kategori</option><?php foreach($categories as $c)echo '<option>'.h($c).'</option>';?></select></div><div class="product-grid" id="productGrid" style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px"><?php foreach($products as $p):?><button type="button" class="product-card text-start" data-id="<?=$p['id']?>" data-name="<?=h($p['name'])?>" data-sku="<?=h($p['sku'])?>" data-category="<?=h($p['category'])?>" data-unit="<?=h($p['unit'])?>" data-price="<?=$p['sell_price']?>" data-stock="<?=$p['stock']?>"><div class="d-flex justify-content-between"><div class="product-icon">▦</div><span class="muted"><?=h($p['stock'])?> <?=h($p['unit'])?></span></div><div class="product-name"><?=h($p['name'])?></div><div class="muted"><?=h($p['sku'])?> · <?=h($p['category'])?></div><div class="fw-bold text-success mt-2"><?=rupiah($p['sell_price'])?></div></button><?php endforeach;?></div><div id="noProducts" class="text-center text-secondary py-5" hidden>Barang tidak ditemukan.</div></section><aside class="card cart-panel p-3"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 fw-bold mb-0">Keranjang</h2><button class="btn btn-sm btn-outline-secondary" id="clearCart">Kosongkan</button></div><div id="cartLines" class="cart-lines"><div class="text-center text-secondary py-5">Pilih barang untuk memulai transaksi.</div></div><div class="border-top pt-3 mt-2"><div class="d-flex justify-content-between mb-3"><span class="text-secondary">Total</span><strong class="fs-4" id="cartTotal">Rp 0</strong></div><label class="form-label">Metode pembayaran</label><select class="form-select mb-3" id="paymentMethod"><option>Tunai</option><option>QRIS</option><option>Transfer</option></select><label class="form-label">Uang diterima (tunai)</label><input type="number" min="0" class="form-control mb-2" id="paidInput" placeholder="Masukkan nominal"><div class="d-flex justify-content-between small mb-3"><span class="text-secondary">Kembalian</span><b id="changeAmount">Rp 0</b></div><button class="btn btn-success btn-lg w-100" id="checkoutBtn">Selesaikan transaksi</button><div class="muted mt-2">QRIS/transfer dicatat sebagai lunas secara manual pada prototipe ini. Pastikan pembayaran diterima.</div></div><form id="checkoutForm" method="post" hidden><input name="checkout" value="1"><input name="cart_json" id="cartJson"><input name="payment_method" id="formMethod"><input name="paid" id="formPaid"></form></aside></div>
<?php elseif($page==='barang'):?><div class="row g-3"><div class="col-12 col-xl-4"><div class="card p-3 p-lg-4"><h2 class="h5 fw-bold mb-3"><?=$edit?'Edit barang':'Tambah barang'?></h2><form method="post"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><div class="mb-3"><label class="form-label">SKU / kode barang</label><input class="form-control" name="sku" required value="<?=h($edit['sku']??'')?>" placeholder="Contoh: BRG001"></div><div class="mb-3"><label class="form-label">Nama barang</label><input class="form-control" name="name" required value="<?=h($edit['name']??'')?>"></div><div class="row g-2"><div class="col-7 mb-3"><label class="form-label">Kategori</label><input class="form-control" name="category" required value="<?=h($edit['category']??'Sembako')?>"></div><div class="col-5 mb-3"><label class="form-label">Satuan</label><input class="form-control" name="unit" required value="<?=h($edit['unit']??'pcs')?>" placeholder="kg/pcs"></div><div class="col-6 mb-3"><label class="form-label">Harga modal</label><input class="form-control" type="number" min="0" name="cost_price" required value="<?=h($edit['cost_price']??0)?>"></div><div class="col-6 mb-3"><label class="form-label">Harga jual</label><input class="form-control" type="number" min="0" name="sell_price" required value="<?=h($edit['sell_price']??0)?>"></div><div class="col-6 mb-3"><label class="form-label">Stok</label><input class="form-control" type="number" min="0" step="0.001" name="stock" required value="<?=h($edit['stock']??0)?>"></div><div class="col-6 mb-3"><label class="form-label">Stok minimum</label><input class="form-control" type="number" min="0" step="0.001" name="min_stock" required value="<?=h($edit['min_stock']??0)?>"></div></div><button class="btn btn-success w-100" name="save_product" value="1">Simpan barang</button><?php if($edit):?><a class="btn btn-light w-100 mt-2" href="?page=barang">Batal edit</a><?php endif;?></form></div></div><div class="col-12 col-xl-8"><div class="card p-3 p-lg-4"><div class="d-flex justify-content-between gap-2 mb-3"><h2 class="h5 fw-bold">Daftar barang (<?=$productCount?>)</h2><input id="tableSearch" class="form-control" style="max-width:220px" placeholder="Cari barang..."></div><div class="table-wrap"><table class="table" id="productsTable"><thead><tr><th>Barang</th><th>Harga jual</th><th>Stok</th><th>Aksi</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><b><?=h($p['name'])?></b><div class="muted"><?=h($p['sku'])?> · <?=h($p['category'])?></div></td><td><?=rupiah($p['sell_price'])?><div class="muted">Modal <?=rupiah($p['cost_price'])?></div></td><td><?=h($p['stock'])?> <?=h($p['unit'])?><?php if($p['stock']<=$p['min_stock'])echo '<div><span class="badge text-bg-warning">Stok rendah</span></div>';?></td><td><div class="d-flex gap-1"><a class="btn btn-sm btn-outline-success" href="?page=barang&edit=<?=$p['id']?>">Edit</a><form method="post" onsubmit="return confirm('Hapus barang ini?')"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-sm btn-outline-danger" name="delete_product" value="1">Hapus</button></form></div></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php elseif($page==='transaksi'):?><div class="card p-3 p-lg-4"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 fw-bold">Transaksi terbaru</h2><button class="btn btn-outline-secondary btn-sm" onclick="window.print()">Cetak halaman</button></div><div class="table-wrap"><table class="table"><thead><tr><th>No. Invoice</th><th>Tanggal</th><th>Total</th><th>Metode</th><th>Status</th></tr></thead><tbody><?php foreach($sales as $s):?><tr><td><b><?=h($s['invoice'])?></b></td><td><?=date('d/m/Y H:i',strtotime($s['created_at']))?></td><td><?=rupiah($s['total'])?></td><td><?=h($s['payment_method'])?></td><td><span class="badge badge-soft"><?=h($s['status'])?></span></td></tr><?php endforeach;if(!$sales)echo '<tr><td colspan="5" class="text-center text-secondary">Belum ada transaksi.</td></tr>';?></tbody></table></div><div class="muted">Menampilkan maksimal 100 transaksi terbaru.</div></div>
<?php elseif($page==='laporan'):?><div class="row g-3 mb-4"><div class="col-12 col-md-4"><div class="card metric"><small>Total penjualan sepanjang waktu</small><strong><?=rupiah($pdo->query('SELECT COALESCE(SUM(total),0) FROM sales')->fetchColumn())?></strong></div></div><div class="col-12 col-md-4"><div class="card metric"><small>Estimasi laba kotor sepanjang waktu</small><strong><?=rupiah($pdo->query('SELECT COALESCE(SUM(line_total-qty*cost_price),0) FROM sale_items')->fetchColumn())?></strong></div></div><div class="col-12 col-md-4"><div class="card metric"><small>Total pengeluaran tercatat</small><strong><?=rupiah($pdo->query('SELECT COALESCE(SUM(amount),0) FROM expenses')->fetchColumn())?></strong></div></div></div><div class="row g-3"><div class="col-12 col-xl-5"><div class="card p-3 p-lg-4"><h2 class="h5 fw-bold mb-3">Catat pengeluaran</h2><form method="post"><div class="mb-3"><label class="form-label">Keterangan</label><input class="form-control" name="title" required placeholder="Contoh: listrik toko"></div><div class="mb-3"><label class="form-label">Nominal (Rp)</label><input class="form-control" name="amount" type="number" min="0" required></div><div class="mb-3"><label class="form-label">Tanggal</label><input class="form-control" name="expense_date" type="date" required value="<?=date('Y-m-d')?>"></div><button class="btn btn-success w-100" name="save_expense" value="1">Simpan pengeluaran</button></form></div></div><div class="col-12 col-xl-7"><div class="card p-3 p-lg-4"><h2 class="h5 fw-bold mb-3">Pengeluaran terbaru</h2><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Keterangan</th><th>Nominal</th></tr></thead><tbody><?php foreach($pdo->query('SELECT * FROM expenses ORDER BY expense_date DESC,id DESC LIMIT 50') as $e):?><tr><td><?=h($e['expense_date'])?></td><td><?=h($e['title'])?></td><td><?=rupiah($e['amount'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php elseif($page==='pengaturan'):?><div class="row g-3"><div class="col-12 col-lg-6"><div class="card p-3 p-lg-4"><h2 class="h5 fw-bold mb-3">Ganti password</h2><form method="post"><div class="mb-3"><label class="form-label">Password saat ini</label><input type="password" name="current_password" class="form-control" required></div><div class="mb-3"><label class="form-label">Password baru (minimal 10 karakter)</label><input type="password" name="new_password" class="form-control" minlength="10" required></div><div class="mb-3"><label class="form-label">Ulangi password baru</label><input type="password" name="confirm_password" class="form-control" minlength="10" required></div><button class="btn btn-success" name="change_password" value="1">Ubah password</button></form></div></div><div class="col-12 col-lg-6"><div class="card p-3 p-lg-4"><h2 class="h5 fw-bold">Informasi aplikasi</h2><p class="text-secondary">Sembako POS — prototipe awal untuk satu pemilik toko.</p><ul class="text-secondary"><li>Web responsif desktop, tablet, dan HP.</li><li>Database MySQL.</li><li>Pembayaran QRIS/transfer dicatat manual; belum terhubung ke penyedia pembayaran.</li><li>Backup database perlu dilakukan dari hosting atau phpMyAdmin.</li></ul><div class="alert alert-warning mb-0">Sebelum dipublikasikan online, aktifkan HTTPS, gunakan password database yang kuat, lindungi setup.php, dan siapkan backup rutin.</div></div></div></div><?php else:?><div class="card p-4">Halaman tidak ditemukan. <a href="?page=dashboard">Kembali ke dashboard</a></div><?php endif;?></main>
