<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>
const money=n=>'Rp '+Math.round(n).toLocaleString('id-ID');
const search=document.getElementById('searchProduct'),filter=document.getElementById('categoryFilter'),grid=document.getElementById('productGrid');function filterProducts(){if(!grid)return;let q=(search.value||'').toLowerCase(),c=filter.value;let visible=0;grid.querySelectorAll('.product-card').forEach(b=>{let ok=(b.dataset.name.toLowerCase().includes(q)||b.dataset.sku.toLowerCase().includes(q))&&(!c||b.dataset.category===c);b.hidden=!ok;if(ok)visible++});document.getElementById('noProducts').hidden=visible>0;}if(search){search.addEventListener('input',filterProducts);filter.addEventListener('change',filterProducts)}
let cart={};function total(){return Object.values(cart).reduce((s,p)=>s+p.qty*p.price,0)}function renderCart(){let el=document.getElementById('cartLines');if(!el)return;let items=Object.values(cart);el.innerHTML=items.length?items.map(p=>`<div class="cart-line"><div class="d-flex justify-content-between gap-2"><div><b>${esc(p.name)}</b><div class="muted">${money(p.price)} / ${esc(p.unit)}</div></div><button class="btn btn-sm btn-light text-danger" onclick="removeItem(${p.id})">×</button></div><div class="d-flex align-items-center justify-content-between mt-2"><div class="btn-group btn-group-sm"><button class="btn btn-outline-secondary" onclick="changeQty(${p.id},-1)">−</button><span class="btn btn-light disabled">${p.qty}</span><button class="btn btn-outline-secondary" onclick="changeQty(${p.id},1)">+</button></div><b>${money(p.qty*p.price)}</b></div></div>`).join(''):'<div class="text-center text-secondary py-5">Pilih barang untuk memulai transaksi.</div>';document.getElementById('cartTotal').textContent=money(total());updateChange()}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function changeQty(id,d){if(!cart[id])return;let p=cart[id],el=document.querySelector(`.product-card[data-id="${id}"]`);p.qty=Math.max(0,Math.min(Number(el.dataset.stock),p.qty+d));if(!p.qty)delete cart[id];renderCart()}function removeItem(id){delete cart[id];renderCart()}function updateChange(){let t=total(),m=document.getElementById('paymentMethod')?.value,p=Number(document.getElementById('paidInput')?.value||0);document.getElementById('changeAmount').textContent=money(m==='Tunai'?Math.max(0,p-t):0)}document.querySelectorAll('.product-card').forEach(b=>b.addEventListener('click',()=>{let id=Number(b.dataset.id),stock=Number(b.dataset.stock);if(stock<=0){alert('Stok barang habis.');return}if(!cart[id])cart[id]={id,name:b.dataset.name,unit:b.dataset.unit,price:Number(b.dataset.price),qty:0,stock};if(cart[id].qty<stock)cart[id].qty++;else alert('Jumlah melebihi stok tersedia.');renderCart()}));document.getElementById('clearCart')?.addEventListener('click',()=>{cart={};renderCart()});document.getElementById('paidInput')?.addEventListener('input',updateChange);document.getElementById('paymentMethod')?.addEventListener('change',()=>{let isCash=document.getElementById('paymentMethod').value==='Tunai';document.getElementById('paidInput').disabled=!isCash;updateChange()});document.getElementById('checkoutBtn')?.addEventListener('click',()=>{let t=total();if(!t){alert('Keranjang masih kosong.');return}let method=document.getElementById('paymentMethod').value,paid=method==='Tunai'?Number(document.getElementById('paidInput').value||0):t;if(method==='Tunai'&&paid<t){alert('Uang diterima kurang dari total belanja.');return}if(!confirm('Selesaikan transaksi sebesar '+money(t)+' melalui '+method+'? Pastikan pembayaran digital telah diterima.'))return;document.getElementById('cartJson').value=JSON.stringify(Object.values(cart).map(p=>({id:p.id,qty:p.qty})));document.getElementById('formMethod').value=method;document.getElementById('formPaid').value=paid;document.getElementById('checkoutForm').submit()});document.getElementById('tableSearch')?.addEventListener('input',e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('#productsTable tbody tr').forEach(r=>r.hidden=!r.innerText.toLowerCase().includes(q))});
</script></body></html>
